def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    result = []
    current_char = texto[0]
    count = 1

    for char in texto[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    result.append(f"{current_char}{count}")
    return "".join(result)

def iniciales(nombre: str) -> str:
    # Split the string by any whitespace to get words
    words = nombre.split()

    # For each word, take the first letter and convert to uppercase
    result = []
    for word in words:
        if word:  # Ensure word is not empty (though split already avoids empty strings)
            result.append(word[0].upper())

    # Join all the initial letters into a single string
    return ''.join(result)

def aplanar(datos: list) -> list:
    result = []
    for item in datos:
        if isinstance(item, (list, tuple)):
            result.extend(aplanar(item))
        else:
            result.append(item)
    return result

def parsear_fecha(texto: str) -> str:
    # Convert to lowercase for month names
    texto_lower = texto.lower().strip()

    # Format 1: AAAA-MM-DD
    if '-' in texto_lower:
        parts = texto_lower.split('-')
        if len(parts) == 3:
            year_str, month_str, day_str = parts
            if len(year_str) == 4 and len(month_str) == 2 and len(day_str) == 2:
                try:
                    year = int(year_str)
                    month = int(month_str)
                    day = int(day_str)
                    # Validate month
                    if month < 1 or month > 12:
                        raise ValueError
                    # Validate day based on month and year
                    days_in_month = [31, 28, 29, 31, 30, 31, 30, 31, 30, 31, 30, 31]
                    if month == 2 and is_leap_year(year):
                        max_day = 29
                    else:
                        max_day = days_in_month[month-1]
                    if day < 1 or day > max_day:
                        raise ValueError
                    return f"{year}-{month:02d}-{day:02d}"
                except ValueError:
                    raise ValueError
    # Format 2: DD/MM/AAAA
    elif '/' in texto_lower:
        parts = texto_lower.split('/')
        if len(parts) == 3:
            day_str, month_str, year_str = parts
            if len(day_str) == 2 and len(month_str) == 2 and len(year_str) == 4:
                try:
                    day = int(day_str)
                    month = int(month_str)
                    year = int(year_str)
                    # Validate month
                    if month < 1 or month > 12:
                        raise ValueError
                    # Validate day
                    days_in_month = [31, 28, 29, 31, 30, 31, 30, 31, 30, 31, 30, 31]
                    if month == 2 and is_leap_year(year):
                        max_day = 29
                    else:
                        max_day = days_in_month[month-1]
                    if day < 1 or day > max_day:
                        raise ValueError
                    return f"{year}-{month:02d}-{day:02d}"
                except ValueError:
                    raise ValueError
    # Format 3: D de MES de AAAA
    else:
        parts = texto_lower.split()
        if len(parts) == 4:
            day_str, _, month_name, _, year_str = parts
            # Validate year
            if len(year_str) != 4:
                raise ValueError
            try:
                year = int(year_str)
                # Normalize month name
                months = {
                    'enero': 1, 'febrero': 2, 'marzo': 3, 'abril': 4,
                    'mayo': 5, 'junio': 6, 'julio': 7, 'agosto': 8,
                    'septiembre': 9, 'octubre': 10, 'noviembre': 11, 'diciembre': 12
                }
                month_name_lower = month_name.lower()
                if month_name_lower not in months:
                    raise ValueError
                month = months[month_name_lower]
                # Validate day
                try:
                    day = int(day_str)
                except ValueError:
                    raise ValueError
                # Validate day for February in leap year
                days_in_month = [31, 28, 29, 31, 30, 31, 30, 31, 30, 31, 30, 31]
                if month == 2 and is_leap_year(year):
                    max_day = 29
                else:
                    max_day = days_in_month[month-1]
                if day < 1 or day > max_day:
                    raise ValueError
                return f"{year}-{month:02d}-{day:02d}"
            except ValueError:
                raise ValueError
    # If none of the formats match
    raise ValueError

def is_leap_year(year: int) -> bool:
    """Check if a year is a leap year."""
    # Rule: divisible by 4, but not by 100 unless also divisible by 400
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    # Validate inputs
    if len(pesos) != len(valores):
        raise ValueError("pesos y valores deben tener la misma longitud")
    if any(p < 0 for p in pesos) or capacidad < 0:
        raise ValueError("pesos no pueden ser negativos y capacidad no puede ser negativa")

    n = len(pesos)
    # Initialize dp table: for each capacity, store best combination (value, weight, count, indices)
    dp = [(0, 0, 0, []) for _ in range(capacidad + 1)]

    # Helper function to compare two combinations
    def is_better(a, b):
        if a[0] > b[0]:
            return True
        if a[0] < b[0]:
            return False
        if a[1] < b[1]:
            return True
        if a[1] > b[1]:
            return False
        if a[2] < b[2]:
            return True
        if a[2] > b[2]:
            return False
        return a[3] < b[3]

    for i in range(n):
        w = pesos[i]
        v = valores[i]
        # Iterate capacities from high to low to ensure 0/1 property
        for cap in range(capacidad, w - 1, -1):
            # Candidate if we take item i
            candidate = (v + dp[cap - w][0], dp[cap - w][1] + w, dp[cap - w][2] + 1, dp[cap - w][3] + [i])
            # Current best without taking item i
            current = dp[cap]
            if is_better(candidate, current):
                dp[cap] = candidate

    return dp[capacidad]

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("La capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Mark the key as recently used
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if clave in self._datos:
            # Update existing key and mark as recently used
            self._datos.move_to_end(clave)
            self._datos[clave] = valor
        else:
            # Key is new
            if len(self._datos) < self.capacidad:
                # Cache has space, add the new key-value
                self._datos[clave] = valor
            else:
                # Cache is full, remove least recently used
                self._datos.popitem(last=False)
                self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
